/* Disposable local prototype. No production API, telemetry or provider calls. */
(() => {
'use strict';
const TOPICS=window.DEMO_TOPICS, sources=window.demoSources;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',book:'M12 6c-3-2-6-2-9-1v14c3-1 6-1 9 1m0-14c3-2 6-2 9-1v14c-3-1-6-1-9 1V6',pen:'m15 4 5 5M4 20l5-1L21 7l-5-5L4 14v6',right:'m9 5 7 7-7 7',left:'m15 5-7 7 7 7',arrow:'M4 12h16m-6-6 6 6-6 6',search:'M15 15l5 5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',bookmark:'M6 3h12v18l-6-4-6 4V3',check:'m5 12 4 4L19 6',plus:'M12 4v16M4 12h16',x:'m6 6 12 12M18 6 6 18',expand:'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',copy:'M8 8h13v13H8zM16 8V3H3v13h5',up:'m6 14 6-6 6 6',down:'m6 10 6 6 6-6',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.book}"/></svg>`;
const button=(text,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const KEY='linggan-workbench-prototype-v3';
let persisted={};try{persisted=JSON.parse(localStorage.getItem(KEY)||'{}')}catch{}
const state={page:['today','reading','studio'].includes(persisted.view?.page)?persisted.view.page:'today',selected:TOPICS.some(t=>t.id===persisted.view?.selected)?persisted.view.selected:1,filter:'全部',search:'',variant:Math.max(0,Math.min(2,Number(new URL(location.href).searchParams.get('variant'))||0)),source:persisted.view?.source||'scene',step:Math.max(0,Math.min(3,Number(persisted.view?.step)||0)),inner:Math.max(0,Number(persisted.view?.inner)||0),focus:false,saved:true,drafts:persisted.drafts||{},bookmarks:Array.isArray(persisted.bookmarks)?persisted.bookmarks:[],exported:false};
const topic=()=>TOPICS.find(t=>t.id===state.selected)||TOPICS[0];
function newDraft(t){return {title:t.title,body:'',cover:t.cover,subtitle:t.subtitle,template:'type',color:'green',pages:t.outline.map((v,i)=>({id:'page-'+t.id+'-'+i,title:v[0],body:''})),clips:[],links:[]};}
function draft(){if(!state.drafts[state.selected])state.drafts[state.selected]=newDraft(topic());return state.drafts[state.selected]}
function save(){try{localStorage.setItem(KEY,JSON.stringify({drafts:state.drafts,bookmarks:state.bookmarks,view:{page:state.page,selected:state.selected,source:state.source,step:state.step,inner:state.inner,researchView:state.researchView,researchSource:state.researchSource,browser:browse}}));state.saved=true}catch{state.saved=false}const el=$('#save-state');if(el){el.textContent=state.saved?'':'保存失败，请先导出';el.classList.toggle('error',!state.saved)}state.exported=false;}
let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
let lastFocus;
function modal(title,body,actions=''){lastFocus=document.activeElement;const el=$('#dialog');el.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${button(icon('x'),'close','ghost icon-btn','aria-label="关闭弹窗"')}</div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!el.open)el.showModal();}
function closeModal(){const el=$('#dialog');if(el.open)el.close();lastFocus?.isConnected&&lastFocus.focus();}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeModal()});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal()});
function navigate(page){state.page=page;state.focus=page==='studio'?state.focus:false;closeModal();render();window.scrollTo(0,0);$('#page-title')?.focus({preventScroll:true});}
function selectTopic(id){state.selected=Number(id);state.source='scene';state.inner=0;state.exported=false;}
function shell(content){const names={today:'今日选题',reading:'研读取材',studio:'图文创作'};return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="brand-mark">i</span><span class="brand-name">intelligence</span></div><div class="domain"><strong class="ops-label">运营</strong><span>家庭日常 · 演示领域</span></div><nav class="nav" aria-label="工作台导航">${[['today','sun'],['reading','book'],['studio','pen']].map(([p,i])=>`<button class="${state.page===p?'active':''}" data-action="nav" data-page="${p}" ${state.page===p?'aria-current="page"':''} aria-label="${names[p]}">${icon(i)}<span class="nav-text">${names[p]}</span></button>`).join('')}</nav><div class="sidebar-note">${state.page==='today'?'今天，从一篇好内容开始。':`当前选题<strong>${esc(topic().title)}</strong>`}</div><div class="sidebar-bottom"><div class="row"><span class="avatar">M</span><div class="user-name"><div class="small">Mog 的工作台</div><div class="small muted">个人创作空间</div></div></div>${button(`${icon('info')} 原型说明`,'about','ghost')}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>运营</span><span>/</span><span>${names[state.page]}</span>${state.focus?'<span class="long-crumb">· 沉浸模式</span>':''}</div><button class="prototype-label" data-action="about">V3 原型 · 演示内容</button></header><main id="main" class="main" tabindex="-1">${content}</main></div></div>`;}
function filtered(){return TOPICS.filter(t=>(state.filter==='全部'||(state.filter==='已收藏'?state.bookmarks.includes(t.id):t.tag===state.filter))&&`${t.title} ${t.angle}`.includes(state.search))}
function brief(t=topic(),inModal=false){return `<section class="brief" aria-label="完整选题方案"><div class="row between"><span class="eyebrow">选题方案 <span class="mono">${String(t.id).padStart(2,'0')}</span></span>${button(icon('bookmark'),'bookmark','ghost icon-btn',`aria-label="${state.bookmarks.includes(t.id)?'取消收藏':'收藏选题'}" aria-pressed="${state.bookmarks.includes(t.id)}" data-id="${t.id}"`)}</div><h2 class="brief-title">${esc(t.title)}</h2><p class="brief-lead">${esc(t.angle)}</p><div class="brief-actions">${button(`研读材料 ${icon('arrow')}`,'start-reading','primary',`data-id="${t.id}"`)}${button('直接创作','start-studio','ghost',`data-id="${t.id}"`)}</div><div class="brief-section"><h3>写给谁</h3><p>${esc(t.reader)}</p></div><div class="brief-section"><h3>为什么值得写 · 演示判断</h3><p>${esc(t.reason)}</p></div><div class="brief-section"><h3>图文怎么展开</h3><ol class="outline">${t.outline.map(v=>`<li>${esc(v[0])}</li>`).join('')}</ol></div><div class="brief-section"><div class="row between"><h3>可用材料</h3><span class="small muted">18 份演示材料</span></div>${[['note','6 篇原笔记'],['voice','8 条用户原声'],['similar','4 个相似选题']].map(([kind,label])=>`<button class="material-link" data-action="v2-start-library" data-id="${t.id}" data-filter="${kind}">${icon('book')}<span class="grow">${label}</span>${icon('right')}</button>`).join('')}</div></section>`;}
function topicRow(t){return `<button class="topic-row ${t.id===state.selected?'selected':''}" data-action="select-topic" data-id="${t.id}" aria-pressed="${t.id===state.selected}"><span class="topic-number">${String(t.id).padStart(2,'0')}</span><span class="grow"><span class="tag ${t.id===state.selected?'accent':''}">${esc(t.tag)}${state.bookmarks.includes(t.id)?' · 已收藏':''}</span><h2>${esc(t.title)}</h2><p>${esc(t.angle)}</p></span><span class="topic-arrow">${icon('right')}</span></button>`;}
function todayResults(){const rows=filtered();if(!rows.length)return `<div class="empty">${icon('search')}<h2>暂时没有匹配的选题</h2><p class="muted">试试其他词，或回到全部 10 个方案。</p>${button('清除筛选','clear-filter')}</div>`;
 if(state.variant===0)return `<div class="topic-layout"><div class="topic-list">${rows.map(topicRow).join('')}</div>${brief()}</div>`;
 if(state.variant===1)return [...new Set(rows.map(t=>t.tag))].map(tag=>`<section class="board-group"><div class="row between"><h2 style="font-size:var(--f15)">${esc(tag)}</h2><span class="small muted">${rows.filter(t=>t.tag===tag).length} 个方案</span></div><div class="board-grid">${rows.filter(t=>t.tag===tag).map(t=>`<button class="board-card ${state.selected===t.id?'selected':''}" data-action="show-brief" data-id="${t.id}"><div class="board-art">${esc(t.cover)}</div><div class="board-copy"><h2>${esc(t.title)}</h2><p>${esc(t.angle)}</p></div></button>`).join('')}</div></section>`).join('');
 const t=rows.find(t=>t.id===state.selected)||rows[0];return `<div class="focus-topic"><div class="big-num">${String(t.id).padStart(2,'0')}</div><div>${brief(t)}<div class="focus-nav">${button(`${icon('left')} 上一篇`,'prev-topic','ghost')}<span class="selection-count">${rows.indexOf(t)+1} / ${rows.length}</span>${button(`下一篇 ${icon('right')}`,'next-topic','ghost')}</div></div></div>`;
}
function today(){return `<h1 class="visually-hidden" id="page-title" tabindex="-1">今日选题</h1><div class="toolbar"><div class="tabs" aria-label="选题筛选">${['全部','日常陪伴','沟通表达','已收藏'].map(s=>`<button class="${state.filter===s?'active':''}" data-action="filter" data-filter="${s}" aria-pressed="${state.filter===s}">${s}${s==='全部'?' 10':''}</button>`).join('')}</div><label class="search">${icon('search')}<input id="topic-search" aria-label="搜索选题" placeholder="搜索选题或角度" value="${esc(state.search)}"></label></div><div id="topic-results">${todayResults()}</div><div class="variant-bar" aria-label="比较选题页面布局"><span class="label">布局比较</span>${button(icon('left'),'prev-variant','icon-btn','aria-label="上一种布局"')}<span class="name">${['A · 编辑台','B · 选题墙','C · 单篇决策'][state.variant]}</span>${button(icon('right'),'next-variant','icon-btn','aria-label="下一种布局"')}<div class="variant-dots">${['A','B','C'].map((s,i)=>`<button class="${i===state.variant?'active':''}" data-action="variant" data-variant="${i}" aria-label="布局 ${s}" aria-pressed="${i===state.variant}">${s}</button>`).join('')}</div></div>`;}
function render(){document.body.classList.toggle('research-mode',state.page==='reading');document.body.classList.toggle('compare-mode',state.page==='studio'&&state.step===0&&state.writeView==='compare');save();document.body.classList.toggle('immersed',state.focus&&state.page==='studio');$('#app').innerHTML=shell(state.page==='today'?today():state.page==='reading'?reading():studio());if(state.page==='studio'){renderCanvases();autoSize();}afterV2Render();afterV3Render();}
function autoSize(){document.querySelectorAll('.title-editor,.body-editor').forEach(el=>{el.style.height='auto';el.style.height=el.scrollHeight+'px';});}
// Remaining page functions and actions are below.
function basketContent(){const d=draft();return d.clips.length?d.clips.map(c=>`<div class="basket-item"><p>${esc(c.text)}</p><div class="row"><span class="small muted">${esc(c.sourceName)}</span>${state.page==='studio'?button('插入正文','insert-clip','ghost',`data-key="${c.key}"`):''}${button(icon('x'),'remove-clip','ghost icon-btn',`data-key="${c.key}" aria-label="移除摘录：${esc(c.text.slice(0,14))}"`)}</div></div>`).join(''):'<p class="basket-empty">遇到想用的原文，把它加入素材。创作时还可以随时回来查看。</p>';}
function readingV1(){const t=topic(),d=draft(),s=sources(t).find(v=>v.id===state.source)||sources(t)[0];return `<div class="reading-header"><div class="row between">${button(`${icon('left')} 返回选题`,'nav','ghost','data-page="today"')}<span class="small muted">当前选题的材料 · 演示内容</span></div><h1 id="page-title" tabindex="-1">${esc(t.title)}</h1></div><div class="reading-grid"><nav class="source-nav" aria-label="材料列表">${sources(t).map(v=>`<button class="source-button ${v.id===s.id?'selected':''}" data-action="source" data-source="${v.id}" aria-pressed="${v.id===s.id}"><span class="eyebrow">${v.kind}</span><strong>${v.name}</strong></button>`).join('')}</nav><article class="reading-paper"><span class="eyebrow">${s.kind}</span><h2>${s.name}</h2><p class="source-note">${s.meta}</p>${s.paragraphs.map((p,i)=>{const key=s.id+'-'+i,added=d.clips.some(c=>c.key===key);return `<section class="reading-paragraph ${s.id==='voice'?'voice':''}"><p>${esc(p)}</p><div class="quote-action">${button(`${icon(added?'check':'plus')} ${added?'已加入素材':'加入素材'}`,'clip','ghost '+(added?'added':''),`data-source="${s.id}" data-index="${i}" aria-label="${added?'移除':'加入'}第 ${i+1} 段素材" aria-pressed="${added}"`)}</div></section>`}).join('')}<p class="hint" style="margin-top:var(--s24)">这些材料为原型编写，用于体验阅读、摘录与引用。正式内容需要真实来源支撑。</p></article><aside class="basket"><div class="row between"><h3>这篇的素材</h3><span class="mono small muted">${d.clips.length}</span></div>${basketContent()}</aside></div><div class="reading-footer"><span class="small muted">${d.clips.length?`已选 ${d.clips.length} 段素材，进入创作后仍可查阅。`:'也可以先进入创作，随后再补充素材。'}</span>${button(`开始图文创作 ${icon('arrow')}`,'start-studio','primary',`data-id="${t.id}"`)}</div>`;}
function studio(){const d=draft();return `<h1 class="visually-hidden" id="page-title" tabindex="-1">图文创作</h1><div class="studio-command-row"><nav class="steps" aria-label="创作步骤">${['正文','封面','内页','预览与导出'].map((s,i)=>`<button class="step ${state.step===i?'active':''}" data-action="step" data-step="${i}" ${state.step===i?'aria-current="step"':''}><span class="num">0${i+1}</span>${s}</button>`).join('')}</nav><div class="row studio-actions">${button(`${icon('book')} 素材 ${d.clips.length}`,'show-clips','ghost')}${button(`${icon('expand')} ${state.focus?'退出沉浸':'沉浸创作'}`,'focus','ghost')}</div></div><span class="saved ${state.saved?'':'error'}" id="save-state" role="status">${state.saved?'':'保存失败，请先导出'}</span>${state.step===0?writing():state.step===1?cover():state.step===2?innerPages():preview()}`;}
function writingV1(){const d=draft(),t=topic();return `<div class="studio-body"><section class="writing"><label for="post-title">笔记标题</label><textarea id="post-title" class="title-editor" data-field="title" rows="2" placeholder="给这篇内容起个标题">${esc(d.title)}</textarea><label for="post-body" class="skip-link">正文内容</label><textarea id="post-body" class="body-editor" data-field="body" placeholder="从一个你想写的场景开始……">${esc(d.body)}</textarea><div class="editor-meta"><span id="word-count">${d.body.replace(/\s/g,'').length} 字</span><span>本地演示草稿 · 离开后可继续</span></div></section><aside class="writing-aside"><div class="aside-section" style="border-top:0;padding-top:0"><h3>这一篇的角度</h3><p>${esc(t.angle)}</p></div><div class="aside-section"><h3>提纲</h3><ol class="outline">${t.outline.map(v=>`<li>${esc(v[0])}</li>`).join('')}</ol></div><div class="aside-section"><h3>写作辅助</h3>${button(`${icon('spark')} 看看另一种开头`,'rewrite','ghost')}<p class="hint" style="margin-top:var(--s8)">演示改写，预览后再决定是否采用。</p></div><div class="aside-section">${button(`${icon('book')} 继续研读材料`,'nav','ghost','data-page="reading"')}</div></aside></div><div class="studio-footer"><span class="hint">先把话说清楚，再让图片帮你表达。</span>${button(`制作封面 ${icon('arrow')}`,'step','primary','data-step="1"')}</div>`;}
function templateControls(){const d=draft();return `<div><span class="field-label">整组排版</span><div class="template-picks">${[['type','留白大字','大字'],['split','双色分栏','Aa'],['list','清单笔记','01']].map(([id,label,s])=>`<button class="template-btn ${d.template===id?'active':''}" data-action="template" data-template="${id}" aria-pressed="${d.template===id}"><div class="template-thumb ${id}">${s}</div>${label}</button>`).join('')}</div></div><div><span class="field-label">强调色</span><div class="color-picks">${[['orange','橙红'],['green','墨绿'],['ink','冷黑']].map(([id,label])=>`<button class="color-btn ${d.color===id?'active':''}" data-action="color" data-color="${id}" aria-label="${label}" aria-pressed="${d.color===id}"><span class="${id}"></span></button>`).join('')}</div></div>`;}
function canvasStage(kind='cover',i=0){return `<div class="canvas-stage"><canvas class="poster" data-kind="${kind}" data-index="${i}" width="1080" height="1440" role="img" aria-label="${kind==='cover'?'封面':'内页 '+(i+1)}实时预览"></canvas><div class="stage-caption"><span>${kind==='cover'?'封面':'内页 '+(i+1)}</span><span class="mono">1080 × 1440 · 3:4</span></div></div>`;}
function cover(){const d=draft();return `<div class="studio-visual">${canvasStage()}<aside class="image-controls"><label class="field">封面标题<textarea rows="3" id="cover-title" data-field="cover">${esc(d.cover)}</textarea></label><div class="row">${button('从笔记标题带入','v3-cover-title','ghost')}${d.previousCover!==undefined?button('撤销带入','v3-undo-cover','ghost'):''}</div><label class="field">封面副标题<textarea rows="2" data-field="subtitle">${esc(d.subtitle)}</textarea></label>${templateControls()}<p class="hint">换行会保留在图片里。排版与强调色同步应用于内页。</p><div id="image-warning"></div></aside></div><div class="studio-footer">${button(`${icon('left')} 返回正文`,'step','ghost','data-step="0"')}${button(`编辑内页 ${icon('arrow')}`,'step','primary','data-step="2"')}</div>`;}
function innerPages(){const d=draft();ensureLinks();state.inner=Math.max(0,Math.min(state.inner,d.pages.length-1));const p=d.pages[state.inner];return `<div class="row between"><span class="small muted">封面之后的 ${d.pages.length} 张内页</span><span class="hint">点击切换，调整顺序</span></div><div class="page-strip" aria-label="内页顺序">${d.pages.map((v,i)=>`<button class="page-thumb ${state.inner===i?'active':''}" data-action="inner-select" data-index="${i}" aria-label="编辑内页 ${i+1}：${esc(v.title)}" aria-pressed="${state.inner===i}"><canvas data-kind="inner" data-index="${i}" width="1080" height="1440" aria-hidden="true"></canvas><span class="small">${String(i+1).padStart(2,'0')} · 内页</span></button>`).join('')}<button class="page-thumb add" data-action="add-page" ${d.pages.length>=9?'disabled':''} aria-label="添加内页">${icon('plus')}<span class="small">添加内页</span></button></div><div class="studio-visual">${canvasStage('inner',state.inner)}<aside class="image-controls"><div class="row between"><h2 style="font-size:var(--f17)">第 ${state.inner+1} 页</h2><span class="small muted">与封面保持一致</span></div><label class="field">内页标题<input id="inner-title" data-field="inner-title" value="${esc(p.title)}"></label><label class="field">内页正文<textarea rows="6" data-field="inner-body">${esc(p.body)}</textarea></label><div class="page-tools"><div class="row">${button(icon('left'),'move-page','icon-btn',`data-direction="-1" aria-label="内页前移" ${state.inner===0?'disabled':''}`)}${button(icon('right'),'move-page','icon-btn',`data-direction="1" aria-label="内页后移" ${state.inner===d.pages.length-1?'disabled':''}`)}</div>${button(`${icon('trash')} 删除`,'delete-page','ghost',d.pages.length<=1?'disabled':'')}</div><p class="hint">每页只讲一件事，文字太多时可以拆成下一页。最多 9 张内页。</p>${pageSources(p)}<div id="image-warning"></div></aside></div><div class="studio-footer">${button(`${icon('left')} 返回封面`,'step','ghost','data-step="1"')}${button(`整组预览 ${icon('arrow')}`,'step','primary','data-step="3"')}</div>`;}
function validation(){const d=draft(),issues=[];if(!d.title.trim())issues.push('补上笔记标题');if(!d.body.trim())issues.push('补上正文内容');const c=document.createElement('canvas');c.width=1080;c.height=1440;issues.push(...drawPoster(c,'cover',0));d.pages.forEach((p,i)=>issues.push(...drawPoster(c,'inner',i)));return [...new Set(issues)];}
function preview(){const d=draft(),issues=validation();return `<div class="page-heading"><div><h2>最后看一遍，然后发布你的表达。</h2><p>共 ${d.pages.length+1} 张图片 · 点击可放大检查或单独下载</p></div></div><div class="preview-layout"><div class="preview-grid">${['cover',...d.pages.map(()=> 'inner')].map((k,i)=>`<button class="preview-item" data-action="preview-image" data-kind="${k}" data-index="${Math.max(0,i-1)}" aria-label="放大${i===0?'封面':'内页 '+i}"><canvas data-kind="${k}" data-index="${Math.max(0,i-1)}" width="1080" height="1440" aria-hidden="true"></canvas><span class="row between"><span>${i===0?'封面':'内页 '+String(i).padStart(2,'0')}</span>${icon('expand')}</span></button>`).join('')}</div><aside class="export-panel"><div><h3 style="margin-bottom:var(--s16)">笔记正文</h3><div class="export-copy"><strong>${esc(d.title)}</strong>\n\n${esc(d.body)}</div>${button(`${icon('copy')} 复制标题与正文`,'copy-body','ghost','style="margin-top:var(--s12)"')}</div><div><h3 style="margin-bottom:var(--s16)">导出前检查</h3>${issues.length?issues.map(s=>`<div class="check-row bad">${icon('info')}<span>${esc(s)}</span></div>`).join(''):`<div class="check-row">${icon('check')}<span>标题与正文已填写</span></div><div class="check-row">${icon('check')}<span>${d.pages.length+1} 张图片完整，文字未溢出</span></div><div class="check-row">${icon('check')}<span>封面与内页风格一致</span></div>`}<p class="hint" style="margin:var(--s16) 0">导出包含 PNG 图片、正文和演示说明。这是合成内容，请用于验收体验。正文和内页保留取材关联，编辑后的文字以当前版本导出。请检查整组表达。</p>${button(`${icon('download')} 下载图文包`,'export','primary',issues.length?'disabled':'')}<p class="hint" style="margin-top:var(--s8)">ZIP · 1080 × 1440 · 无需联网</p></div><div class="full" id="export-result"></div></aside></div><div class="studio-footer">${button(`${icon('left')} 继续编辑`,'step','ghost','data-step="2"')}<span class="hint">成品导出不等于已发布。</span></div>`;}
/* One deterministic canvas renderer is shared by preview and exported PNG. */
const PALETTES={orange:'#e6532f',green:'#137557',ink:'#0b0f12'};
function wrapText(ctx,text,width){const lines=[];for(const para of String(text).split('\n')){let line='';for(const char of para){if(line&&ctx.measureText(line+char).width>width){const chars=Array.from(line),last=chars.at(-1);if(chars.length>1&&(/[，。、；：！？）》」』】％%…]/u.test(char)||/[（「『【《]/u.test(last))){chars.pop();lines.push(chars.join(''));line=last+char;}else{lines.push(line);line=char;}}else line+=char;}lines.push(line);}return lines;}

function drawPoster(canvas,kind,index){const d=draft(),ctx=canvas.getContext('2d'),W=1080,H=1440,accent=PALETTES[d.color]||PALETTES.orange,cream='#f4efe5',ink='#0b0f12';const font='"PingFang SC","Noto Sans SC","Microsoft YaHei",sans-serif';canvas.width=W;canvas.height=H;ctx.textBaseline='top';let issues=[];
 const rect=(x,y,w,h,color)=>{ctx.fillStyle=color;ctx.fillRect(x,y,w,h)};
 const text=(s,x,y,size=32,color=ink,weight=400)=>{ctx.font=`${weight} ${size}px ${font}`;ctx.fillStyle=color;ctx.fillText(s,x,y)};
 const block=(s,x,y,size,width,lineHeight,maxLines,color=ink,weight=600,field='文字')=>{ctx.font=`${weight} ${size}px ${font}`;const lines=wrapText(ctx,s,width);if(lines.length>maxLines)issues.push(`${field}太长，请缩短或拆页`);lines.slice(0,maxLines).forEach((l,i)=>text(l,x,y+i*lineHeight,size,color,weight));return Math.min(lines.length,maxLines)*lineHeight};
 rect(0,0,W,H,d.template==='list'?'#ffffff':cream);
 const footer=()=>{rect(80,1300,920,2,'#0b0f1230');text('家庭日常   /   创作演示',80,1334,24,'#5f6a71');text(kind==='cover'?'COVER':String(index+1).padStart(2,'0'),900,1334,24,'#5f6a71')};
 if(kind==='cover'){
  if(!d.cover.trim())issues.push('补上封面标题');if(!d.subtitle.trim())issues.push('补上封面副标题');
  if(d.template==='split'){rect(0,0,W,1000,accent);text('日常观察   /   一点新思路',80,92,28,'#ffffff');rect(80,192,72,8,'#ffffff');block(d.cover,80,280,104,920,148,4,'#ffffff',600,'封面标题');block(d.subtitle,80,1090,42,920,66,2,ink,400,'封面副标题')}
  else if(d.template==='list'){rect(0,0,W,40,ink);text('日常生活，慢慢练习。',80,104,28,'#5f6a71');block(d.cover,80,280,104,920,150,4,ink,700,'封面标题');rect(80,984,920,240,'#dce6d8');rect(80,984,12,240,accent);block(d.subtitle,128,1038,40,824,64,2,ink,400,'封面副标题')}
  else{rect(80,96,16,48,accent);text('家庭日常   /   一点新思路',120,105,28,'#5f6a71');block(d.cover,80,300,104,920,156,4,ink,600,'封面标题');rect(80,1016,100,8,accent);block(d.subtitle,80,1080,40,920,64,2,ink,400,'封面副标题')}
 }else{const p=d.pages[index];if(!p)return ['内页不存在'];if(!p.title.trim())issues.push(`补上内页 ${index+1} 标题`);if(!p.body.trim())issues.push(`补上内页 ${index+1} 正文`);
  if(d.template==='split'){rect(0,0,W,192,accent);text(String(index+1).padStart(2,'0'),80,62,72,'#ffffff',600);text('一个可以尝试的小改变',228,92,28,'#ffffff');}else{text(String(index+1).padStart(2,'0'),80,88,80,accent,600);text('一个可以尝试的小改变',228,118,28,'#5f6a71');}
  const hh=block(p.title,80,304,76,920,112,3,ink,600,`内页 ${index+1} 标题`);rect(80,344+hh,100,6,accent);const by=424+hh;block(p.body,80,by,48,920,84,Math.max(1,Math.floor((1224-by)/84)),ink,400,`内页 ${index+1} 正文`);
 }
 footer();return issues;}
function renderCanvases(){document.querySelectorAll('canvas[data-kind]').forEach(c=>drawPoster(c,c.dataset.kind,Number(c.dataset.index)));const w=$('#image-warning');if(w){const c=document.createElement('canvas');c.width=1080;c.height=1440;const issues=drawPoster(c,state.step===1?'cover':'inner',state.inner);w.innerHTML=issues.map(s=>`<p class="warning">${esc(s)}</p>`).join('');}}
function imageDialog(kind,index){modal(kind==='cover'?'检查封面':`检查内页 ${index+1}`,`<canvas class="poster" data-kind="${kind}" data-index="${index}" width="1080" height="1440" role="img" aria-label="导出前图片预览"></canvas>`,button('返回预览','close','ghost')+button(`${icon('download')} 下载这张 PNG`,'download-image','primary',`data-kind="${kind}" data-index="${index}"`));renderCanvases();}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function imageBlob(kind,index){const c=document.createElement('canvas');const issues=drawPoster(c,kind,index);if(issues.length)throw Error(issues.join('；'));return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('图片未生成，请重试')),'image/png'));}
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=(n&1)?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc32(bytes){let crc=0xffffffff;for(const b of bytes)crc=crcTable[(crc^b)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function zip(files){const parts=[],central=[];let offset=0;const utf8=new TextEncoder();for(const file of files){const name=utf8.encode(file.name),data=file.bytes,crc=crc32(data),local=new Uint8Array(30+name.length),v=new DataView(local.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x800,true);v.setUint16(12,0x21,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);local.set(name,30);parts.push(local,data);const dir=new Uint8Array(46+name.length),dv=new DataView(dir.buffer);dv.setUint32(0,0x02014b50,true);dv.setUint16(4,20,true);dv.setUint16(6,20,true);dv.setUint16(8,0x800,true);dv.setUint16(14,0x21,true);dv.setUint32(16,crc,true);dv.setUint32(20,data.length,true);dv.setUint32(24,data.length,true);dv.setUint16(28,name.length,true);dv.setUint32(42,offset,true);dir.set(name,46);central.push(dir);offset+=local.length+data.length;}const size=central.reduce((n,c)=>n+c.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});}
async function exportPackage(btn){const issues=validation();if(issues.length){toast(issues[0]);return}btn.disabled=true;btn.textContent='正在生成文件…';try{const d=draft(),files=[],encoder=new TextEncoder();for(let i=0;i<=d.pages.length;i++){const b=await imageBlob(i===0?'cover':'inner',Math.max(0,i-1));files.push({name:i===0?'00-cover.png':`${String(i).padStart(2,'0')}-page.png`,bytes:new Uint8Array(await b.arrayBuffer())});}files.push({name:'正文.txt',bytes:encoder.encode(`${d.title}\n\n${d.body}\n`)});files.push({name:'原型说明.txt',bytes:encoder.encode('Intelligence 内容工作台交互原型。所有选题、材料及图文均为演示内容，不是真实研究成果。\n图片规格 1080×1440，为本轮体验提案；未接入发布平台或 AI 模型。\n文件顺序：00-cover 为封面，其余按数字排序。\n')});files.push({name:'manifest.json',bytes:encoder.encode(JSON.stringify({prototype:true,topicId:state.selected,title:d.title,imageSize:[1080,1440],template:d.template,color:d.color,images:files.filter(f=>f.name.endsWith('.png')).map(f=>f.name),clips:d.clips,canvasNotes:d.canvasNotes||{},prototypeVersion:3,sourceLinks:exportLinks(),pages:d.pages.map(p=>({id:p.id,title:p.title,body:p.body})),body:d.body},null,2))});download(zip(files),`intelligence-v3-demo-${state.selected}.zip`);state.exported=true;$('#export-result').innerHTML=`<div class="export-result"><strong>图文包已生成，下载已发起</strong><span>${d.pages.length+1} 张 PNG 图片 + 正文 + 演示说明</span><span class="hint">请在浏览器下载记录中确认文件已保存。</span></div>`;toast('演示图文包已生成')}catch(e){toast('导出失败：'+e.message)}finally{btn.disabled=false;btn.innerHTML=icon('download')+' 再次下载图文包';}}
function setVariant(i){state.variant=(i+3)%3;const u=new URL(location.href);u.searchParams.set('variant',state.variant);history.replaceState(null,'',u);render();}
let deletedPage=null, rewriteText='';
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,d=draft();if(a.startsWith('v3-')){await handleV3Action(b);return;}if(a.startsWith('v2-')){await handleV2Action(b);return;}
 switch(a){
 case 'close':closeModal();break;
 case 'nav':navigate(b.dataset.page);break;
 case 'select-topic':selectTopic(b.dataset.id);$('#topic-results').innerHTML=todayResults();if(innerWidth<=650){modal('完整选题方案',brief());}break;
 case 'show-brief':selectTopic(b.dataset.id);modal('完整选题方案',brief());break;
 case 'start-reading':selectTopic(b.dataset.id);state.researchView='read';state.researchSource='n1';state.librarySearch='';state.libraryFilter='all';state.sourcePin=null;state.targetParagraph=null;ensureBrowse();Object.assign(browse,{kind:'all',use:'全部',search:'',active:null,spread:0,exact:null});navigate('reading');break;
 case 'read-source':selectTopic(b.dataset.id);state.source=b.dataset.source;navigate('reading');break;
 case 'start-studio':if(Number(b.dataset.id)!==state.selected)selectTopic(b.dataset.id);draft();save();state.step=0;state.writeView='write';navigate('studio');break;
 case 'filter':state.filter=b.dataset.filter;{const rows=filtered();if(rows.length&&!rows.some(t=>t.id===state.selected))selectTopic(rows[0].id)}render();break;
 case 'clear-filter':state.search='';state.filter='全部';render();break;
 case 'bookmark':{const id=Number(b.dataset.id),has=state.bookmarks.includes(id);state.bookmarks=has?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();if($('#dialog').open){$('#dialog .dialog-body').innerHTML=brief();}else render();toast(has?'已取消收藏':'已收藏到选题');break;}
 case 'prev-variant':setVariant(state.variant-1);break;case 'next-variant':setVariant(state.variant+1);break;case 'variant':setVariant(Number(b.dataset.variant));break;
 case 'prev-topic':case 'next-topic':{const rows=filtered(),index=rows.findIndex(t=>t.id===state.selected);if(rows.length)selectTopic(rows[(index+(a==='next-topic'?1:-1)+rows.length)%rows.length].id);render();break;}
 case 'source':state.source=b.dataset.source;render();break;
 case 'clip':{const s=sources(topic()).find(v=>v.id===b.dataset.source),i=Number(b.dataset.index),key=s.id+'-'+i;const has=d.clips.some(c=>c.key===key);d.clips=has?d.clips.filter(c=>c.key!==key):[...d.clips,{key,source:s.id,sourceName:s.kind,text:s.paragraphs[i]}];save();render();toast(has?'已移除摘录':'已加入这篇的素材');break;}
 case 'remove-clip':d.clips=d.clips.filter(c=>c.key!==b.dataset.key);save();if($('#dialog').open){$('#dialog .dialog-body').innerHTML=basketContent();}else render();toast('已移除摘录');break;
 case 'insert-clip':{const c=d.clips.find(c=>c.key===b.dataset.key);if(c){d.body+='\n\n'+c.text+'\n（来源：演示'+c.sourceName+'）';save();closeModal();state.step=0;render();toast('摘录已插入正文末尾，可继续编辑')}break;}
 case 'show-clips':state.researchView='canvas';navigate('reading');break;
 case 'step':state.step=Number(b.dataset.step);state.exported=false;render();window.scrollTo(0,0);break;
 case 'focus':state.focus=!state.focus;render();break;
 case 'rewrite':state.writeView='compare';ensureRevision();render();break;
 case 'legacy-rewrite':rewriteText=`${topic().quote}\n\n这句话让我想把问题问得更具体一点：${topic().angle}`;modal('另一种开头 · 演示改写',`<p class="hint" style="margin-bottom:var(--s16)">以下是预写的演示版本，只替换正文第一段。采用后可以撤销。</p><div class="rewrite">${esc(rewriteText)}</div>`,button('保留原文','close','ghost')+button('采用这个开头','apply-rewrite','primary'));break;
 case 'apply-rewrite':d.previousBody=d.body;d.body=rewriteText+'\n\n'+d.body.split(/\n\s*\n/).slice(1).join('\n\n');save();closeModal();render();modal('开头已替换','<p>正文其余内容已保留。你可以继续编辑，或撤销这次改写。</p>',button('撤销改写','undo-rewrite','ghost')+button('继续编辑','close','primary'));break;
 case 'undo-rewrite':if(d.previousBody!==undefined){d.body=d.previousBody;delete d.previousBody;save()}closeModal();render();toast('已恢复原来的正文');break;
 case 'template':d.template=b.dataset.template;save();render();break;
 case 'color':d.color=b.dataset.color;save();render();break;
 case 'inner-select':state.inner=Number(b.dataset.index);render();break;
 case 'add-page':if(d.pages.length>=9)return;d.pages.push({id:crypto.randomUUID(),title:'新的一页',body:''});state.inner=d.pages.length-1;save();render();$('#inner-title')?.focus();break;
 case 'move-page':{const next=state.inner+Number(b.dataset.direction);if(next<0||next>=d.pages.length)return;[d.pages[state.inner],d.pages[next]]=[d.pages[next],d.pages[state.inner]];state.inner=next;save();render();toast('内页顺序已调整');break;}
 case 'delete-page':if(d.pages.length<=1)return;deletedPage={topicId:state.selected,index:state.inner,page:d.pages[state.inner]};d.pages.splice(state.inner,1);state.inner=Math.max(0,state.inner-1);save();render();modal('已删除这一页','<p>其他内页已按顺序前移。可以撤销这次删除。</p>',button('撤销删除','undo-delete','ghost')+button('继续编辑','close','primary'));break;
 case 'undo-delete':if(deletedPage&&deletedPage.topicId===state.selected){d.pages.splice(deletedPage.index,0,deletedPage.page);state.inner=deletedPage.index;deletedPage=null;save()}closeModal();render();break;
 case 'preview-image':imageDialog(b.dataset.kind,Number(b.dataset.index));break;
 case 'download-image':try{download(await imageBlob(b.dataset.kind,Number(b.dataset.index)),b.dataset.kind==='cover'?'00-cover.png':`${String(Number(b.dataset.index)+1).padStart(2,'0')}-page.png`);toast('图片下载已发起')}catch(e){toast(e.message)}break;
 case 'export':await exportPackage(b);break;
 case 'copy-body':try{await navigator.clipboard.writeText(d.title+'\n\n'+d.body);toast('标题与正文已复制')}catch{modal('复制正文',`<label class="field">可手动全选复制<textarea rows="12" readonly>${esc(d.title+'\n\n'+d.body)}</textarea></label>`)}break;
 case 'about':modal('这是一个可以动手试的工作台',`<div class="stack"><p>今日选题 → 研读取材 → 创作画布 → 正文 → 封面 → 内页 → 导出。选题页底部可比较三种布局，完整创作流程一致。</p><p>全部内容为演示，材料与相似选题数量不是系统实际结果。改稿以本地示例开始，可以手动修改，差异按真实文字计算。没有连接真实账号、材料库、AI 模型或发布平台。</p><p>草稿自动保存在这个浏览器中。下载的图片和正文是实际文件，可用来检查排版；演示内容不作为真实研究或发布建议。</p><p>原型画布使用 1080×1440。平台适配、真实生成和可靠保存将作为后续业务能力实现。</p></div>`,button('重置演示草稿','reset-request','ghost')+button('开始体验','close','primary'));break;
 case 'reset-request':modal('重置本原型的演示草稿？','<p>只重置本浏览器内这个原型的编辑、摘录和收藏。重置后可以在本次页面会话中撤销。</p>',button('保留草稿','close','ghost')+button('重置演示','reset','primary'));break;
 case 'reset':state.resetBackup={drafts:state.drafts,bookmarks:state.bookmarks};state.drafts={};state.bookmarks=[];state.inner=0;save();closeModal();render();modal('演示草稿已重置','<p>已恢复演示内容。</p>',button('撤销重置','undo-reset','ghost')+button('继续体验','close','primary'));break;
 case 'undo-reset':if(state.resetBackup){state.drafts=state.resetBackup.drafts;state.bookmarks=state.resetBackup.bookmarks;delete state.resetBackup;save()}closeModal();render();break;
 }
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='topic-search'){state.search=el.value;const rows=filtered();if(rows.length&&!rows.some(t=>t.id===state.selected))selectTopic(rows[0].id);$('#topic-results').innerHTML=todayResults();return}if(handleV3Input(el)||handleV2Input(el))return;const f=el.dataset.field;if(!f)return;const d=draft();if(f==='inner-title'){d.pages[state.inner].title=el.value;document.querySelector(`[data-action="inner-select"][data-index="${state.inner}"]`)?.setAttribute('aria-label',`编辑内页 ${state.inner+1}：${el.value}`);}else if(f==='inner-body')d.pages[state.inner].body=el.value;else d[f]=el.value;save();if(f==='body')$('#word-count').textContent=d.body.replace(/\s/g,'').length+' 字';if(f==='body'||f==='title')autoSize();if(state.step===1||state.step===2)renderCanvases();refreshLinkStatuses();});
document.addEventListener('keydown',e=>{if(state.page!=='today'||$('#dialog').open||e.target.closest('input,textarea,select,[contenteditable]')||e.altKey||e.metaKey||e.ctrlKey)return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();setVariant(state.variant+(e.key==='ArrowRight'?1:-1));}});
/* V2: evidence selection, structured writing canvas, and real local revision diff. */
const LANES=[['inbox','待整理','先留下想用的片段'],['opening','开头','一个场景，或一个具体问题'],['argument','论点','这篇想讲清楚什么'],['example','例子','细节、原声和不同声音'],['ending','结尾','带走的想法或一个行动']];
Object.assign(state,{researchView:persisted.view?.researchView||'read',researchSource:persisted.view?.researchSource||'n1',libraryFilter:'all',librarySearch:'',fragmentFilter:'全部',sourcePin:null,writeView:'write',revisionEditing:false,diffVisible:true,syncScroll:true,selection:null,targetParagraph:null});
const library=()=>window.researchSources(topic());
const currentSource=()=>library().find(s=>s.id===state.researchSource)||library()[0];
function boardDraft(){const d=draft();if(!d.canvasNotes)d.canvasNotes={};return d;}
const kindLabel=k=>({note:'原笔记',voice:'用户原声',similar:'相似选题'}[k]||'材料');
function visibleSources(){return library().filter(s=>(state.libraryFilter==='all'||s.kind===state.libraryFilter)&&(`${s.title} ${s.author} ${s.paras.join(' ')}`.includes(state.librarySearch)));}
function sourceFilters(){const all=library();return `<div class="source-filters" aria-label="材料类型">${[['all','全部'],['note','原笔记'],['voice','用户原声'],['similar','相似选题']].map(([id,label])=>`<button data-action="v2-filter" data-filter="${id}" class="${state.libraryFilter===id?'active':''}" aria-pressed="${state.libraryFilter===id}"><span>${label}</span><span class="mono">${id==='all'?all.length:all.filter(s=>s.kind===id).length}</span></button>`).join('')}</div>`;}
function libraryPanel(){const rows=visibleSources();return `<aside class="source-library">${sourceFilters()}<p class="source-count">${rows.length} 个演示结果 · 未连接真实语料库</p><div class="source-results">${rows.length?rows.map(s=>`<div class="source-entry ${currentSource().id===s.id?'selected':''}"><button class="source-entry-main" data-action="v2-source" data-source="${s.id}" aria-label="阅读：${esc(s.title)}" aria-pressed="${currentSource().id===s.id}"><span class="source-entry-meta"><i class="source-dot ${s.kind}"></i>${esc(s.origin)}</span><div class="source-entry-title">${esc(s.title)}</div><span class="source-entry-meta">${esc(s.author)}</span></button><div class="source-entry-actions"><span>${s.kind==='voice'?'带原帖上下文':s.paras.length+' 段内容'}</span><button data-action="v2-pin" data-source="${s.id}" aria-label="并排对照：${esc(s.title)}">并排对照</button></div></div>`).join(''):`<div class="tray-empty"><strong>没有匹配的材料</strong>试试其他词。${button('清除检索','v2-clear-search','ghost')}</div>`}</div></aside>`;}
function hasClip(source,index,text){return boardDraft().clips.some(c=>c.sourceId===source&&c.paragraph===index&&c.text===text);}
function sourceArticle(s){const d=boardDraft(),parent=s.parent&&library().find(v=>v.id===s.parent);return `<article class="source-paper" aria-label="原文：${esc(s.title)}"><div class="row between"><span class="eyebrow">${kindLabel(s.kind)} · ${esc(s.origin)}</span>${state.sourcePin?button(icon('x'),'v2-unpin','ghost icon-btn','aria-label="退出双篇对照"'):''}</div><h2>${esc(s.title)}</h2><div class="source-paper-meta"><span>${esc(s.author)}</span><span>${esc(s.meta)}</span></div>${parent?`<button class="context-link" data-action="v2-source" data-source="${parent.id}">来自原笔记：${esc(parent.title)} ${icon('right')}</button>`:''}<div class="read-help">选中文字，可把准确片段放入创作画布。</div><div class="source-content">${s.paras.map((p,i)=>{const added=hasClip(s.id,i,p),target=state.targetParagraph?.source===s.id&&state.targetParagraph?.index===i;return `<section class="source-para ${s.kind==='voice'?'voice':''} ${target?'target':''}" data-source-id="${s.id}" data-paragraph="${i}" id="paragraph-${s.id}-${i}"><p data-selectable="true">${target&&state.targetParagraph.range?esc(p.slice(0,state.targetParagraph.range.start))+'<mark class="source-highlight">'+esc(p.slice(state.targetParagraph.range.start,state.targetParagraph.range.end))+'</mark>'+esc(p.slice(state.targetParagraph.range.end)):esc(p)}</p><div class="para-footer"><span>${esc(s.labels[i]||'片段')} · 第 ${i+1} 段</span>${button(`${icon(added?'check':'plus')} ${added?'已在画布':'摘取这一段'}`,'v2-take-paragraph','ghost '+(added?'added':''),`data-source="${s.id}" data-index="${i}" aria-label="摘取 ${s.id} 第 ${i+1} 段"`)}</div></section>`}).join('')}</div>${s.discussion?.length?`<section class="source-context-comments"><div class="row between"><h3>这篇下面的讨论</h3><span class="small muted">${s.discussion.length} 条演示原声</span></div>${s.discussion.map(id=>{const v=library().find(v=>v.id===id);return `<div class="discussion-entry"><p>${esc(v.paras[0])}</p><div class="row between"><span class="small muted">${v.author}</span>${button(`${icon('plus')} 放入画布`,'v2-take-paragraph','ghost',`data-source="${v.id}" data-index="0" aria-label="摘取原声 ${v.id}"`)}</div></div>`}).join('')}</section>`:''}<p class="hint" style="margin-top:var(--s16)">当前为合成内容。正式接入时保留原帖、作者、时间、段落位置与材料完整状态。</p></article>`;}
function clipCardLegacy(c,full=false){return `<article class="clip-card ${c.kind==='voice'?'voice':''}" draggable="true" data-clip-id="${esc(c.key)}" aria-label="画布片段：${esc(c.text.slice(0,24))}" tabindex="0"><div class="clip-kind"><span>${kindLabel(c.kind)}</span><button class="clip-grab" data-grab="${esc(c.key)}" aria-label="拖动片段：${esc(c.text.slice(0,12))}" title="拖到另一组；也可用下方菜单移动">⠿</button></div><blockquote>${esc(c.text)}</blockquote><button class="clip-source" data-action="v2-locate" data-key="${esc(c.key)}" aria-label="回到出处：${esc(c.sourceTitle)}">↗ ${esc(c.sourceTitle)} · 第 ${c.paragraph+1} 段</button>${full?`<textarea class="clip-thought" data-clip-thought="${esc(c.key)}" aria-label="我的想法：${esc(c.text.slice(0,18))}" placeholder="我的想法：这一段为什么值得用？">${esc(c.thought||'')}</textarea>`:''}<div class="clip-actions"><select data-clip-lane="${esc(c.key)}" aria-label="片段用途：${esc(c.text.slice(0,18))}">${LANES.map(([id,label])=>`<option value="${id}" ${(c.lane||'inbox')===id?'selected':''}>${label}</option>`).join('')}</select>${full?button(icon('up'),'v2-clip-up','ghost icon-btn',`data-key="${esc(c.key)}" aria-label="片段前移：${esc(c.text.slice(0,12))}"`):''}${button(icon('x'),'v2-remove','ghost icon-btn',`data-key="${esc(c.key)}" aria-label="移除画布片段：${esc(c.text.slice(0,12))}"`)}</div></article>`;}
function canvasTray(){const d=boardDraft();return `<aside class="canvas-tray"><div class="tray-head"><h2>这篇的创作画布</h2><span class="mono small">${d.clips.length}</span></div><p class="source-bridge">来源留在片段上，思路留给你。</p><div class="tray-cards">${d.clips.length?d.clips.map(c=>clipCard(c)).join(''):`<div class="tray-empty"><strong>先选一段真正想用的</strong>可以是读者的一句话、一篇笔记里的细节，或与当前想法不同的观点。</div>`}</div><div class="tray-footer">${button(`${icon('grid')} 展开创作画布`,'v2-view','','data-view="canvas"')}${button(`进入正文 ${icon('arrow')}`,'v2-write','primary')}</div></aside>`;}
function fragmentView(){let rows=visibleSources().flatMap(s=>s.paras.map((text,i)=>({s,i,text,label:s.labels[i]||'片段'})));if(state.fragmentFilter!=='全部')rows=rows.filter(r=>r.label===state.fragmentFilter);if(state.librarySearch)rows=rows.filter(r=>r.text.includes(state.librarySearch)||r.s.title.includes(state.librarySearch));return `<div class="fragment-toolbar" aria-label="片段用途筛选">${['全部','场景','观点','做法','原声','边界'].map(v=>`<button data-action="v2-fragment-filter" data-filter="${v}" class="${state.fragmentFilter===v?'active':''}" aria-pressed="${state.fragmentFilter===v}">${v}</button>`).join('')}<span class="small muted">${rows.length} 段</span></div><div class="fragment-grid">${rows.map(r=>`<article class="fragment"><div class="row between"><span class="fragment-type">${esc(r.label)}</span><span class="small muted">${kindLabel(r.s.kind)}</span></div><p>${esc(r.text)}</p><button class="clip-source" data-action="v2-locate-fragment" data-source="${r.s.id}" data-index="${r.i}">↗ ${esc(r.s.title)}</button><div class="row between" style="margin-top:var(--s8)"><span class="small muted">${r.s.author}</span>${button(icon(hasClip(r.s.id,r.i,r.text)?'check':'plus'),'v2-take-paragraph','ghost icon-btn',`data-source="${r.s.id}" data-index="${r.i}" aria-label="摘取 ${r.s.id} 第 ${r.i+1} 段"`)}</div></article>`).join('')}</div>${!rows.length?'<div class="tray-empty">这个条件下没有片段，换个用途或检索词试试。</div>':''}`;}
function canvasView(){const d=boardDraft();return `<div class="canvas-board" aria-label="按文章结构组织的创作画布">${LANES.map(([id,title])=>{const cards=d.clips.filter(c=>(c.lane||'inbox')===id);return `<section class="canvas-lane" data-lane="${id}" aria-label="${title}区"><div class="lane-title"><span>${title}</span><span class="mono muted">${cards.length}</span></div>${cards.length?cards.map(c=>clipCard(c,true)).join(''):'<div class="lane-empty">拖入片段</div>'}${id!=='inbox'?`<textarea class="lane-note" data-lane-note="${id}" aria-label="${title}：我的表达" placeholder="写下我的表达">${esc(d.canvasNotes[id]||'')}</textarea>`:''}</section>`}).join('')}</div><div class="canvas-summary"><span>${d.clips.length} 个片段 · ${new Set(d.clips.map(c=>c.sourceId)).size} 个来源 · 本地演示草稿</span>${button(`组装为写作底稿 ${icon('arrow')}`,'v2-assemble','primary')}</div>`;}
function readingLegacy(){const d=boardDraft(),s=currentSource(),pinned=state.sourcePin&&library().find(v=>v.id===state.sourcePin);return `<div class="research-head"><div><div class="research-kicker">本篇工作区 / 研读取材</div><h1 id="page-title" tabindex="-1">${esc(topic().title)}</h1></div><div class="row"><span class="small muted">已选 <strong>${d.clips.length}</strong> 个片段</span>${button(`进入正文 ${icon('arrow')}`,'v2-write','primary')}</div></div><div class="research-toolbar"><div class="research-views" aria-label="研读工作视图">${[['read','原文研读'],['fragments','片段总览'],['canvas','创作画布']].map(([id,label])=>`<button class="${state.researchView===id?'active':''}" data-action="v2-view" data-view="${id}" aria-pressed="${state.researchView===id}">${label}${id==='canvas'&&d.clips.length?' · '+d.clips.length:''}</button>`).join('')}</div>${state.researchView!=='canvas'?`<label class="research-search">${icon('search')}<input id="research-search" aria-label="检索原笔记、原声或相似选题" placeholder="检索原笔记、原声、相似选题…" value="${esc(state.librarySearch)}"></label>`:button(`${icon('book')} 继续找材料`,'v2-view','ghost','data-view="read"')}</div>${state.researchView==='canvas'?canvasView():`<div class="research-layout ${pinned&&state.researchView==='read'?'two-notes':''}">${libraryPanel()}<div class="read-center">${state.researchView==='fragments'?fragmentView():pinned?`<div class="compare-reading">${sourceArticle(s)}${sourceArticle(pinned)}</div>`:sourceArticle(s)}</div>${canvasTray()}</div>`}`;}
function addClip(sid,index,text,range){const d=boardDraft(),s=library().find(v=>v.id===sid);if(!s||!s.paras[index])return;const actual=text||s.paras[index];if(!s.paras[index].includes(actual)){toast('这段选文不在当前原文中，请重新选择');return}if(hasClip(sid,index,actual)){toast('这个片段已经在画布中');return}d.clips.push({key:`clip-${Date.now()}-${d.clips.length}`,sourceId:sid,source:sid,sourceName:kindLabel(s.kind),sourceTitle:s.title,author:s.author,kind:s.kind,paragraph:index,text:actual,range:range||{start:0,end:actual.length},lane:'inbox',thought:'',used:false});save();render();toast(`已加入创作画布 · 共 ${d.clips.length} 段`);}
function locateClipLegacy(c){state.page='reading';state.researchView='read';state.researchSource=c.sourceId;state.sourcePin=null;state.libraryFilter='all';state.librarySearch='';state.targetParagraph={source:c.sourceId,index:c.paragraph,range:c.range};state.focus=false;closeModal();render();}
function writing(){const d=boardDraft();return `<div class="write-controls"><div class="write-tabs" aria-label="正文工作模式">${[['write','沉浸编辑'],['compare','改稿对照']].map(([id,label])=>`<button class="${state.writeView===id?'active':''}" data-action="v2-write-view" data-view="${id}" aria-pressed="${state.writeView===id}">${label}</button>`).join('')}</div><div class="write-actions">${state.writeView==='compare'?`<div class="revision-toolbar"><div class="row"><label><input type="checkbox" id="diff-visible" ${state.diffVisible?'checked':''}>显示改动</label><label><input type="checkbox" id="sync-scroll" ${state.syncScroll?'checked':''}>联动滚动</label></div></div>`:''}${button(`${icon('grid')} 创作画布 · ${d.clips.length}`,'v2-open-canvas','ghost')}</div></div>${state.writeView==='compare'?revisionView():`<div class="writing-layout"><section class="writing"><label for="post-title">笔记标题</label><textarea id="post-title" class="title-editor" data-field="title" rows="2">${esc(d.title)}</textarea><label for="post-body" class="skip-link">正文内容</label><textarea id="post-body" class="body-editor" data-field="body" placeholder="从选中的片段和自己的想法开始……">${esc(d.body)}</textarea><div class="editor-meta"><span id="word-count">${d.body.replace(/\s/g,'').length} 字</span></div></section><aside class="writing-sources"><h3>这篇的材料与出处</h3>${bodyLinkSummary()}${d.clips.length?d.clips.slice(0,5).map(c=>`<div class="writing-source-item"><span class="tag">${LANES.find(l=>l[0]===(c.lane||'inbox'))[1]} · ${kindLabel(c.kind)}</span><p>${esc(c.text)}</p><div class="row between">${button('回到原文','v2-locate','ghost',`data-key="${esc(c.key)}"`)}${button('用于作品','v3-place','ghost',`data-key="${esc(c.key)}"`)}</div></div>`).join(''):'<p class="hint">还没有选择片段。可以先写，也可以回到研读取材。</p>'}<div style="margin-top:var(--s24)">${button(`${icon('book')} 继续取材`,'v2-open-research','ghost')}</div></aside></div><div class="studio-footer"><div class="row">${button('对照修改正文','v2-write-view','','data-view="compare"')}${d.previousBody!==undefined?button('撤销上次采用','v2-undo-apply','ghost'):''}</div>${button(`制作封面 ${icon('arrow')}`,'step','primary','data-step="1"')}</div>`}`;}
function ensureRevision(){const d=boardDraft();if(!d.revision){let text=d.body.replace('晚上七点，书包还在门口。','晚上七点，书包还在门口。我们已经在这件事上僵持了一会儿。').replace('把「快去写作业」拆成孩子现在能开始的一步。','先把「快去写作业」放一放，看看孩子眼前能开始的那一步。').replace('你家最常卡在哪一步？可以先从一个小场景开始观察。','如果今晚还会遇到同样的时刻，先观察：他到底停在哪一步？');if(text===d.body)text='先从一个具体的生活片段说起。\n\n'+d.body;d.revision={base:d.body,text};save()}return d.revision;}
function diffParts(a,b){const aa=Array.from(a),bb=Array.from(b),n=aa.length,m=bb.length,parts=[];const put=(type,text)=>{if(!text)return;const last=parts.at(-1);if(last?.type===type)last.text+=text;else parts.push({type,text})};if(n*m>4500000){let p=0,q=0;while(p<n&&p<m&&aa[p]===bb[p])p++;while(q<n-p&&q<m-p&&aa[n-q-1]===bb[m-q-1])q++;put('same',aa.slice(0,p).join(''));put('delete',aa.slice(p,n-q).join(''));put('insert',bb.slice(p,m-q).join(''));put('same',aa.slice(n-q).join(''));return parts;}const cols=m+1,table=new Uint16Array((n+1)*cols);for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)table[i*cols+j]=aa[i]===bb[j]?table[(i+1)*cols+j+1]+1:Math.max(table[(i+1)*cols+j],table[i*cols+j+1]);let i=0,j=0;while(i<n&&j<m){if(aa[i]===bb[j]){put('same',aa[i]);i++;j++}else if(table[(i+1)*cols+j]>=table[i*cols+j+1])put('delete',aa[i++]);else put('insert',bb[j++]);}put('delete',aa.slice(i).join(''));put('insert',bb.slice(j).join(''));return parts;}
function revisionView(){const d=boardDraft(),r=ensureRevision(),parts=diffParts(r.base,r.text),count=type=>parts.filter(p=>p.type===type).reduce((n,p)=>n+p.text.replace(/\s/g,'').length,0),markup=side=>parts.filter(p=>p.type!==(side==='before'?'insert':'delete')).map(p=>state.diffVisible&&p.type!=='same'?`<${p.type==='delete'?'del':'ins'}>${esc(p.text)}</${p.type==='delete'?'del':'ins'}>`:esc(p.text)).join(''),stale=d.body!==r.base;return `${stale?`<p class="warning" style="margin-bottom:var(--s16)">正文已在其他步骤修改，请先更新对照底稿，避免覆盖新内容。${button('更新对照底稿','v2-rebase','ghost')}</p>`:''}<div class="revision-pair ${state.revisionEditing?'editing':''}"><section class="revision-panel"><div class="revision-head"><h2>原稿</h2><span class="mono small muted">${r.base.replace(/\s/g,'').length} 字</span></div><div class="revision-text" data-sync="before" aria-label="原稿差异视图">${markup('before')}</div><div class="revision-footer"><span>只读</span></div></section><section class="revision-panel"><div class="revision-head"><h2>改稿</h2><span class="mono small muted">${r.text.replace(/\s/g,'').length} 字</span></div>${state.revisionEditing?`<textarea class="revision-edit" id="revision-editor" aria-label="编辑改稿" data-revision="true">${esc(r.text)}</textarea>`:`<div class="revision-text" data-sync="after" aria-label="改稿差异视图">${markup('after')}</div>`}<div class="revision-footer"><span>新增 ${count('insert')} 字 · 删去 ${count('delete')} 字</span>${button(state.revisionEditing?'完成编辑，查看差异':'编辑改稿','v2-edit-revision','ghost')}</div></section></div><div class="revision-actions"><div class="row">${button('返回正文','v2-write-view','ghost','data-view="write"')}${button(`${icon('check')} 采用整篇改稿`,'v2-apply-revision','primary',stale?'disabled':'')}</div></div>`;}
let lastRemovedClip=null;
function assembledBody(){const d=boardDraft();return LANES.filter(l=>l[0]!=='inbox').map(([id,title])=>{const cards=d.clips.filter(c=>c.lane===id),own=d.canvasNotes[id]?.trim();if(!cards.length&&!own)return '';return `${title}\n\n${own?own+'\n\n':''}${cards.map(c=>`${c.text}\n〔来源：${c.sourceTitle} · 第 ${c.paragraph+1} 段 · 演示材料〕${c.thought?'\n我的想法：'+c.thought:''}`).join('\n\n')}`;}).filter(Boolean).join('\n\n');}
async function handleV2Action(b){const a=b.dataset.action,d=boardDraft();switch(a){
 case 'v2-start-library':selectTopic(b.dataset.id);ensureBrowse();browse.kind=b.dataset.filter;browse.use='全部';browse.search='';browse.active=null;state.libraryFilter=b.dataset.filter;state.librarySearch='';state.researchView='read';state.sourcePin=null;state.researchSource=library().find(s=>s.kind===state.libraryFilter)?.id||'n1';navigate('reading');break;
 case 'v2-view':state.researchView=b.dataset.view;state.targetParagraph=null;render();break;
 case 'v2-source':state.researchSource=b.dataset.source;state.researchView='read';if(state.sourcePin===state.researchSource)state.sourcePin=null;state.targetParagraph=null;render();break;
 case 'v2-filter':state.libraryFilter=b.dataset.filter;state.targetParagraph=null;{const rows=visibleSources();if(rows.length&&!rows.some(s=>s.id===state.researchSource))state.researchSource=rows[0].id;}render();break;
 case 'v2-clear-search':state.librarySearch='';state.libraryFilter='all';state.fragmentFilter='全部';render();break;
 case 'v2-fragment-filter':state.fragmentFilter=b.dataset.filter;render();break;
 case 'v2-pin':state.researchView='read';state.sourcePin=b.dataset.source===currentSource().id?library().find(s=>s.id!==currentSource().id&&s.kind==='note')?.id:b.dataset.source;render();toast('已打开双篇对照');break;
 case 'v2-unpin':state.sourcePin=null;render();break;
 case 'v2-take-paragraph':addClip(b.dataset.source,Number(b.dataset.index));break;
 case 'v2-add-selection':if(state.selection){const s=state.selection;addClip(s.source,s.index,s.text,{start:s.start,end:s.end});state.selection=null;window.getSelection()?.removeAllRanges();}break;
 case 'v2-remove':{const i=d.clips.findIndex(c=>c.key===b.dataset.key);if(i<0)return;lastRemovedClip={id:state.selected,index:i,clip:d.clips[i]};d.clips.splice(i,1);save();render();modal('片段已移出画布','<p>原始材料仍在，可以重新选取。</p>',button('撤销移除','v2-undo-remove','ghost')+button('继续整理','close','primary'));break;}
 case 'v2-undo-remove':if(lastRemovedClip?.id===state.selected){d.clips.splice(lastRemovedClip.index,0,lastRemovedClip.clip);lastRemovedClip=null;save()}closeModal();render();break;
 case 'v2-clip-up':{const i=d.clips.findIndex(c=>c.key===b.dataset.key),c=d.clips[i];if(!c)return;let prev=i-1;while(prev>=0&&(d.clips[prev].lane||'inbox')!==(c.lane||'inbox'))prev--;if(prev>=0){d.clips.splice(i,1);d.clips.splice(prev,0,c);save();render()}else toast('已经是这一组的第一个片段');break;}
 case 'v2-locate':{const c=d.clips.find(c=>c.key===b.dataset.key);if(c)locateClip(c);break;}
 case 'v2-locate-fragment':locateClip({sourceId:b.dataset.source,paragraph:Number(b.dataset.index)});break;
 case 'v2-write':state.step=0;state.writeView='write';navigate('studio');break;
 case 'v2-open-canvas':state.researchView='canvas';navigate('reading');break;
 case 'v2-open-research':state.researchView='read';navigate('reading');break;
 case 'v2-write-view':state.writeView=b.dataset.view;if(state.writeView==='compare')ensureRevision();render();window.scrollTo(0,0);break;
 case 'v2-edit-revision':state.revisionEditing=!state.revisionEditing;render();if(state.revisionEditing)$('#revision-editor')?.focus();break;
 case 'v2-apply-revision':{const r=ensureRevision();if(d.body!==r.base){toast('正文有新修改，请先更新对照底稿');return}d.previousBody=d.body;d.body=r.text;delete d.revision;state.writeView='write';state.revisionEditing=false;save();render();toast('改稿已采用，可以撤销');break;}
 case 'v2-rebase':delete d.revision;ensureRevision();state.revisionEditing=false;save();render();toast('已以当前正文建立新对照');break;
 case 'v2-undo-apply':if(d.previousBody!==undefined){d.body=d.previousBody;delete d.previousBody;delete d.revision;save();render();toast('已恢复采用前的正文')}break;
 case 'v2-insert':{const c=d.clips.find(c=>c.key===b.dataset.key);if(c){d.previousBody=d.body;d.body+='\n\n'+c.text+'\n〔来源：'+c.sourceTitle+' · 第 '+(c.paragraph+1)+' 段 · 演示材料〕';if(c.thought)d.body+='\n我的想法：'+c.thought;c.used=true;save();render();toast('片段已插入正文末尾')}break;}
 case 'v2-assemble':{const body=assembledBody();if(!body){modal('先给片段一个位置','<p>把想用的片段从“待整理”移动到开头、论点、例子或结尾，也可以在对应栏写下自己的表达。待整理的片段不会自动入稿。</p>',button('继续整理','close','primary'));return}modal('把画布组装为写作底稿',`<p class="hint" style="margin-bottom:var(--s16)">按文章结构排列材料与自己的想法，保留来源。采用后会替换当前正文，可以撤销；这不是 AI 成稿。</p><div class="assembly-preview">${esc(body)}</div>`,button('继续整理','close','ghost')+button('采用为底稿','v2-apply-assembly','primary'));break;}
 case 'v2-apply-assembly':{const body=assembledBody();if(!body)return;d.previousBody=d.body;d.body=body;d.clips.forEach(c=>{if(c.lane&&c.lane!=='inbox')c.used=true});save();state.step=0;state.writeView='write';navigate('studio');toast('画布已整理为正文底稿');break;}
 }}
function handleV2Input(el){const d=boardDraft();if(el.id==='research-search'){state.librarySearch=el.value;const rows=visibleSources();if(rows.length&&!rows.some(s=>s.id===state.researchSource))state.researchSource=rows[0].id;const caret=el.selectionStart;render();const input=$('#research-search');input?.focus();input?.setSelectionRange(caret,caret);return true}if(el.dataset.clipThought){const c=d.clips.find(c=>c.key===el.dataset.clipThought);if(c){c.thought=el.value;save()}return true}if(el.dataset.laneNote){d.canvasNotes[el.dataset.laneNote]=el.value;save();return true}if(el.dataset.revision){ensureRevision().text=el.value;save();return true}return false;}
document.addEventListener('change',e=>{const el=e.target,d=boardDraft();if(el.dataset.clipLane){const c=d.clips.find(c=>c.key===el.dataset.clipLane);if(c){c.lane=el.value;save();render();toast('片段已移到'+LANES.find(l=>l[0]===c.lane)[1])}}else if(el.id==='diff-visible'){state.diffVisible=el.checked;render()}else if(el.id==='sync-scroll'){state.syncScroll=el.checked;save()}});
let draggedClip=null,scrollSyncBusy=false,pointerDrag=null;
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-grab]');if(!h)return;e.preventDefault();pointerDrag={key:h.dataset.grab,x:e.clientX,y:e.clientY,moved:false};});
document.addEventListener('pointermove',e=>{if(!pointerDrag)return;if(Math.hypot(e.clientX-pointerDrag.x,e.clientY-pointerDrag.y)<4)return;pointerDrag.moved=true;document.querySelector(`[data-clip-id="${pointerDrag.key}"]`)?.classList.add('dragging');document.querySelectorAll('.canvas-lane.over').forEach(el=>el.classList.remove('over'));document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lane]')?.classList.add('over');});
document.addEventListener('pointerup',e=>{if(!pointerDrag)return;const drag=pointerDrag;pointerDrag=null;const lane=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-lane]');if(drag.moved&&lane){const c=boardDraft().clips.find(c=>c.key===drag.key);if(c){c.lane=lane.dataset.lane;save();render();toast('片段已移到'+LANES.find(l=>l[0]===c.lane)[1]);}}document.querySelectorAll('.dragging,.over').forEach(el=>el.classList.remove('dragging','over'));});
document.addEventListener('pointercancel',()=>{pointerDrag=null;document.querySelectorAll('.dragging,.over').forEach(el=>el.classList.remove('dragging','over'));});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-clip-id]');if(!card)return;draggedClip=card.dataset.clipId;e.dataTransfer.setData('text/plain',draggedClip);e.dataTransfer.effectAllowed='move';card.classList.add('dragging')});
document.addEventListener('dragover',e=>{const lane=e.target.closest('[data-lane]');if(lane&&draggedClip){e.preventDefault();e.dataTransfer.dropEffect='move';lane.classList.add('over')}});
document.addEventListener('dragleave',e=>{const lane=e.target.closest('[data-lane]');if(lane&&!lane.contains(e.relatedTarget))lane.classList.remove('over')});
document.addEventListener('drop',e=>{const lane=e.target.closest('[data-lane]');if(!lane||!draggedClip)return;e.preventDefault();const c=boardDraft().clips.find(c=>c.key===draggedClip);if(c){c.lane=lane.dataset.lane;save();render();toast('片段已移到'+LANES.find(l=>l[0]===c.lane)[1])}draggedClip=null;});
document.addEventListener('dragend',()=>{draggedClip=null;document.querySelectorAll('.dragging,.over').forEach(el=>el.classList.remove('dragging','over'))});
function captureSelection(){if(state.page!=='reading'||state.researchView!=='read')return;const sel=window.getSelection();if(!sel||sel.isCollapsed||!sel.rangeCount){$('#selection-toolbar')?.remove();return}const range=sel.getRangeAt(0),node=range.commonAncestorContainer,parent=node.nodeType===3?node.parentElement:node,para=parent.closest?.('[data-source-id][data-paragraph]'),text=sel.toString();if(!para||!text.trim()||!para.querySelector('[data-selectable]')?.contains(range.startContainer)||!para.querySelector('[data-selectable]')?.contains(range.endContainer)){return}const p=para.querySelector('[data-selectable]'),prefix=range.cloneRange();prefix.selectNodeContents(p);prefix.setEnd(range.startContainer,range.startOffset);const start=prefix.toString().length;state.selection={source:para.dataset.sourceId,index:Number(para.dataset.paragraph),text,start,end:start+text.length};$('#selection-toolbar')?.remove();const bar=document.createElement('div');bar.id='selection-toolbar';bar.innerHTML=`<span class="small">已选 ${Array.from(text).length} 字</span>${button(`${icon('plus')} 放入创作画布`,'v2-add-selection')}`;bar.addEventListener('mousedown',e=>e.preventDefault());document.body.append(bar);const r=range.getBoundingClientRect();bar.style.left=Math.max(12,Math.min(innerWidth-bar.offsetWidth-12,r.left))+'px';bar.style.top=Math.max(12,Math.min(innerHeight-bar.offsetHeight-12,r.bottom+8))+'px';}
document.addEventListener('mouseup',e=>{if(!e.target.closest('#selection-toolbar'))captureSelection()});document.addEventListener('keyup',captureSelection);
function afterV2Render(){$('#selection-toolbar')?.remove();if(state.page==='reading'&&state.targetParagraph){const t=state.targetParagraph;requestAnimationFrame(()=>$('#paragraph-'+t.source+'-'+t.index)?.scrollIntoView({block:'center',behavior:'smooth'}));}document.querySelectorAll('[data-sync]').forEach(el=>el.addEventListener('scroll',()=>{if(!state.syncScroll||scrollSyncBusy)return;const peer=document.querySelector(`[data-sync="${el.dataset.sync==='before'?'after':'before'}"]`);if(!peer)return;scrollSyncBusy=true;peer.scrollTop=el.scrollTop/Math.max(1,el.scrollHeight-el.clientHeight)*Math.max(0,peer.scrollHeight-peer.clientHeight);requestAnimationFrame(()=>{scrollSyncBusy=false})}));}
// V3 material browser and placement functions follow.
/* V3 keeps one fragment identity across paper strips, source pages and the index. */
const browse={kind:'all',use:'全部',search:'',active:null,spread:0,topic:null,exact:null,...persisted.view?.browser};
const USES=['场景','观点','做法','原声','边界'];
let placement=null,placementUndo=null;
function fragments(){
 return library().flatMap(s=>s.paras.flatMap((p,i)=>{
  const label=s.labels[i]||'观点',use=['观察','例子'].includes(label)?'场景':['已有角度','正文','区别'].includes(label)?'观点':label;
  return Array.from(p.matchAll(/[^。！？\n]+[。！？]?/g)).map((m,j)=>({id:s.id+'-'+i+'-'+j,source:s,index:i,start:m.index,end:m.index+m[0].length,text:m[0],use:USES.includes(use)?use:'观点'}));
 }));
}
function matches(f,ignore){return (ignore==='kind'||browse.kind==='all'||f.source.kind===browse.kind)&&(ignore==='use'||browse.use==='全部'||f.use===browse.use)&&(!browse.search||`${f.text} ${f.source.author}`.includes(browse.search));}
function browserRows(){return fragments().filter(f=>matches(f));}
function spreads(){return library().flatMap(s=>Array.from({length:Math.ceil(s.paras.length/2)},(_,i)=>({source:s,start:i*2})));}
function availableSpreads(){const rows=browserRows();return spreads().map((p,i)=>rows.some(f=>f.source.id===p.source.id&&f.index>=p.start&&f.index<p.start+2)?i:-1).filter(i=>i>=0);}
function spreadOf(f){return spreads().findIndex(p=>p.source.id===f.source.id&&p.start===Math.floor(f.index/2)*2);}
function selectFragment(id){const f=fragments().find(f=>f.id===id);if(!f)return;browse.exact=null;browse.active=f.id;browse.spread=spreadOf(f);state.researchSource=f.source.id;}
function ensureBrowse(){
 if(browse.topic!==state.selected){Object.assign(browse,{topic:state.selected,kind:'all',use:'全部',search:'',active:null,spread:0,exact:null});}
 const rows=browserRows();if(!rows.some(f=>f.id===browse.active))browse.active=null;
 if(!browse.active&&rows.length)selectFragment(rows[0].id);
 return rows;
}
function paperSnippet(f){const selected=f.id===browse.active,added=hasClip(f.source.id,f.index,f.text);return `<button class="paper-snippet ${selected?'selected':''} ${added?'collected':''}" data-action="v3-fragment" data-fragment="${f.id}" aria-pressed="${selected}" aria-label="定位片段：${esc(f.text)}"><span>${esc(f.text)}</span>${added?'<i aria-label="已在画布">✓</i>':''}</button>`;}
function filterBar(){const all=fragments();return `<div class="browse-filters"><div class="filter-line" aria-label="材料范围">${[['all','全部材料'],['note','原笔记'],['voice','用户原声'],['similar','相似选题']].map(([id,label])=>`<button data-action="v3-kind" data-value="${id}" aria-pressed="${browse.kind===id}" class="${browse.kind===id?'active':''}">${label}<small>${new Set(all.filter(f=>matches(f,'kind')&&(id==='all'||f.source.kind===id)).map(f=>f.source.id)).size}</small></button>`).join('')}<label class="browse-search">${icon('search')}<input id="browse-search" aria-label="搜索材料中的片段" placeholder="找一句话、一个细节…" value="${esc(browse.search)}"></label></div><div class="filter-line use-filters" aria-label="片段用途">${['全部',...USES].map(label=>`<button data-action="v3-use" data-value="${label}" aria-pressed="${browse.use===label}" class="${browse.use===label?'active':''}">${label}<small>${all.filter(f=>matches(f,'use')&&(label==='全部'||f.use===label)).length}</small></button>`).join('')}<span class="filter-hint">按作者铺开 · 点击纸条，回到原文</span>${browse.kind!=='all'||browse.use!=='全部'||browse.search?button('清除筛选','v3-clear','ghost'):''}</div></div>`;}
function highlightedParagraph(s,index){
 const text=s.paras[index],ranges=browserRows().filter(f=>f.source.id===s.id&&f.index===index),selected=ranges.find(f=>f.id===browse.active);
 const active=browse.exact?.source===s.id&&browse.exact.index===index?browse.exact:selected;
 const cuts=[...new Set([0,text.length,...ranges.flatMap(f=>[f.start,f.end]),...(active?[active.start,active.end]:[])])].sort((a,b)=>a-b);
 return cuts.slice(0,-1).map((start,i)=>{const end=cuts[i+1],hit=active&&start>=active.start&&end<=active.end,matching=ranges.some(f=>start>=f.start&&end<=f.end),part=esc(text.slice(start,end));return hit||matching?`<mark class="${hit?'active-passage':'matching-passage'}">${part}</mark>`:part}).join('');
}
function bookView(){
 const rows=browserRows();if(!rows.length)return `<div class="book-empty"><span class="eyebrow">材料仍在，换个条件继续找</span><h2>这次没有找到相符的片段</h2><p>来源、用途和检索词会一起生效。</p>${button('清除全部筛选','v3-clear','ghost')}</div>`;
 const all=spreads(),spread=all[browse.spread]||all[0],s=spread.source,parent=s.parent&&library().find(n=>n.id===s.parent);
 return `<div class="book-meta"><span>${kindLabel(s.kind)} · ${esc(s.author)}</span><span>材料 ${library().findIndex(n=>n.id===s.id)+1} / ${library().length}</span></div><div class="open-book" data-open-source="${s.id}" data-open-spread="${spread.start}">${[0,1].map(side=>{
  const i=spread.start+side,exists=i<s.paras.length;
  return `<article class="book-leaf ${side?'right-leaf':'left-leaf'}"><div class="leaf-running">${side?'研读取材 / 原文上下文':esc(s.origin)}</div>${side===0?`<h2>${s.kind==='voice'?'读者的一句话':esc(s.title)}</h2>`:''}${exists?`<div class="book-paragraph source-para ${s.kind==='voice'?'voice':''}" data-source-id="${s.id}" data-paragraph="${i}"><p data-selectable="true">${highlightedParagraph(s,i)}</p></div><div class="leaf-paragraph">第 ${i+1} 段 · ${esc(s.labels[i]||'片段')}</div>`:parent?`<div class="parent-context"><span class="eyebrow">这条原声在讨论什么</span><h3>${esc(parent.title)}</h3><p>${esc(parent.paras[0])}</p>${button('翻到这篇原笔记','v3-parent','ghost',`data-source="${parent.id}"`)}</div>`:'<p class="leaf-end">读到这里，留一点自己的判断。</p>'}<footer>${s.kind==='voice'?'合成评论':'合成原文'} <span class="mono">${exists?String(i+1).padStart(2,'0'):'—'}</span></footer></article>`;
 }).join('')}<span class="book-spine" aria-hidden="true"></span></div><div class="book-nav">${button(`${icon('left')} 上一展开页`,'v3-flip','ghost',`data-direction="-1" ${browse.spread===availableSpreads()[0]?'disabled':''}`)}<span>${spread.start+1}–${Math.min(spread.start+2,s.paras.length)} / ${s.paras.length} 段</span>${button(`下一展开页 ${icon('right')}`,'v3-flip','ghost',`data-direction="1" ${browse.spread===availableSpreads().at(-1)?'disabled':''}`)}</div>`;
}
function distribution(){
 const rows=browserRows(),ss=library().filter(s=>rows.some(f=>f.source.id===s.id));
 if(!rows.length)return '';
 return `<div class="index-heading"><h3>片段分布</h3></div><div class="distribution" role="group" aria-label="片段分布索引" style="--source-count:${ss.length}"><div class="index-row"><span></span>${ss.map(s=>`<button class="index-source ${s.id===spreads()[browse.spread]?.source.id?'active':''}" data-action="v3-index-source" data-source="${s.id}" title="${esc(s.title)}" aria-label="定位材料：${esc(s.title)}">${{note:'笔',voice:'声',similar:'题'}[s.kind]}${library().filter(n=>n.kind===s.kind).findIndex(n=>n.id===s.id)+1}</button>`).join('')}</div>${USES.map((label,li)=>`<div class="index-row"><span class="index-label">${label}</span>${ss.map(s=>{const all=fragments().filter(f=>f.source.id===s.id);return `<div class="index-cell tone-${li} ${all.some(f=>f.id===browse.active)?'current-source':''}" style="--cursor-position:${(all.findIndex(f=>f.id===browse.active)+.5)/all.length*100}%">${rows.filter(f=>f.source.id===s.id&&f.use===label).map(f=>`<button class="index-tick ${f.id===browse.active?'active':''}" style="--position:${(all.findIndex(n=>n.id===f.id)+.5)/all.length*100}%" data-action="v3-index" data-fragment="${f.id}" aria-pressed="${f.id===browse.active}" aria-label="索引定位：${esc(f.text)}" title="${esc(f.text)}"></button>`).join('')}</div>`}).join('')}</div>`).join('')}</div>`;
}
function snippetWall(){const rows=browserRows(),authors=[...new Set(rows.map(f=>f.source.author))];return `<div class="wall-heading"><div><h2>片段</h2></div><span class="small muted" id="fragment-result-count">${rows.length} 个片段 · ${new Set(rows.map(f=>f.source.id)).size} 份材料</span></div><div class="snippet-scroll"><div class="snippet-groups">${authors.map((author,i)=>`<section class="snippet-group tone-${i%5}"><h3><button data-action="v3-author" data-author="${esc(author)}" aria-label="只看${esc(author)}的片段">${esc(author)}</button><small>${rows.filter(f=>f.source.author===author).length}</small></h3><div class="paper-strips">${rows.filter(f=>f.source.author===author).map(paperSnippet).join('')}</div></section>`).join('')}</div>${!rows.length?`<div class="empty"><h3>没有匹配的片段</h3>${button('清除全部筛选','v3-clear','ghost')}</div>`:''}</div>`;}
function selectedBrowserFragment(){const f=fragments().find(f=>f.id===browse.active),r=browse.exact;if(f&&r?.source===f.source.id&&r.index===f.index)return {...f,start:r.start,end:r.end,text:f.source.paras[f.index].slice(r.start,r.end)};return f;}
function selectedStrip(){const f=selectedBrowserFragment(),d=boardDraft();return `<div class="selected-strip" aria-live="polite">${f?`<div class="selected-excerpt"><span class="eyebrow">${kindLabel(f.source.kind)} · ${esc(f.source.author)} · 第 ${f.index+1} 段</span><p>${esc(f.text)}</p><span class="selected-source">${esc(f.source.title)}</span></div><div class="selected-actions">${button(`${icon(hasClip(f.source.id,f.index,f.text)?'check':'plus')} ${hasClip(f.source.id,f.index,f.text)?'已在创作画布':'放入创作画布'}`,'v3-take','primary',hasClip(f.source.id,f.index,f.text)?'disabled':'')}${button(`查看画布 · ${d.clips.length}`,'v2-view','ghost','data-view="canvas"')}</div>`:`<p class="muted">选中纸条后，可以在这里加入画布。</p>`}</div>`;}
function reading(){
 ensureLinks();const rows=ensureBrowse(),d=boardDraft(),canvas=state.researchView==='canvas';
 return `<div class="research-head"><div><h1 id="page-title" tabindex="-1">${esc(topic().title)}</h1></div><div class="row">${button(`进入正文 ${icon('arrow')}`,'v2-write','primary')}</div></div><div class="v3-work-tabs"><div class="research-views" aria-label="研读工作视图">${[['read','材料浏览'],['canvas','创作画布']].map(([id,label])=>`<button class="${(canvas?'canvas':'read')===id?'active':''}" data-action="v2-view" data-view="${id}" aria-pressed="${(canvas?'canvas':'read')===id}">${label}${id==='canvas'?' · '+d.clips.length:''}</button>`).join('')}</div></div>${canvas?canvasView():`${filterBar()}<div class="material-stage"><section class="reading-space" aria-label="翻阅原文"><div id="book-view">${bookView()}</div><div id="distribution-view">${distribution()}</div></section><section class="snippet-wall" aria-label="按作者分组的片段">${snippetWall()}</section></div><div id="selected-strip">${selectedStrip()}</div>`}`;
}
function updateBrowser({flip=false,wall=false}={}){
 const oldScroll=$('.snippet-scroll')?.scrollTop||0;
 if(wall){$('.browse-filters').outerHTML=filterBar();$('.snippet-wall').innerHTML=snippetWall();$('.snippet-scroll').scrollTop=oldScroll;}
 $('#book-view').innerHTML=bookView();$('#distribution-view').innerHTML=distribution();$('#selected-strip').innerHTML=selectedStrip();
 document.querySelectorAll('.paper-snippet').forEach(el=>{const on=el.dataset.fragment===browse.active;el.classList.toggle('selected',on);el.setAttribute('aria-pressed',String(on));});
 if(flip){const book=$('.open-book');book?.classList.add('turning');}
 save();
}
function locateClip(c){
 state.page='reading';state.researchView='read';state.focus=false;state.targetParagraph=null;ensureBrowse();
 Object.assign(browse,{kind:'all',use:'全部',search:''});
 const f=fragments().find(f=>f.source.id===c.sourceId&&f.index===c.paragraph&&(f.start===c.range?.start||f.text.includes(c.text)))||fragments().find(f=>f.source.id===c.sourceId&&f.index===c.paragraph);
 if(f){selectFragment(f.id);if(c.range)browse.exact={source:c.sourceId,index:c.paragraph,start:c.range.start,end:c.range.end};}closeModal();render();
}
function ensureLinks(){const d=boardDraft();d.links??=[];d.pages.forEach(p=>{p.id??=crypto.randomUUID()});return d;}
function linkStatus(link){const d=ensureLinks(),target=link.target==='body'?d:d.pages.find(p=>p.id===link.pageId);return !target?'目标内页已删除':target.body.includes(link.inserted)?'文字仍在':'文字已编辑';}
function linkName(link){if(link.target==='body')return '正文';const i=ensureLinks().pages.findIndex(p=>p.id===link.pageId);return i<0?'已删除内页':'内页 '+(i+1);}
function linkChips(c){const links=ensureLinks().links.filter(l=>l.clipKey===c.key);return links.length?`<div class="link-chips">${links.map(l=>`<button data-action="v3-jump-link" data-link="${l.id}" class="link-chip" title="${linkStatus(l)}">↗ ${linkName(l)}${linkStatus(l)!=='文字仍在'?' · '+linkStatus(l):''}</button>`).join('')}</div>`:'';}
function clipCard(c,full=false){const markup=clipCardLegacy(c,full);return markup.replace('</article>',`${linkChips(c)}${full?button('用于正文 / 内页','v3-place','placement-open',`data-key="${c.key}"`):''}</article>`);}
function pageSources(p){const d=ensureLinks(),links=d.links.filter(l=>l.pageId===p.id);return `<section class="page-sources"><h3>这一页的取材</h3>${links.length?links.map(l=>`<div class="page-source"><button class="clip-source" data-action="v3-link-source" data-link="${l.id}">↗ ${esc(l.sourceTitle)} · 第 ${l.paragraph+1} 段</button><small data-link-status="${l.id}">${linkStatus(l)}</small></div>`).join(''):'<p class="hint">在画布里指定这一页，文字和出处会一起过来。</p>'}${button('从画布选一段','v2-open-canvas','ghost')}</section>`;}
function bodyLinkSummary(){const links=ensureLinks().links.filter(l=>l.target==='body');return `<p class="hint body-link-summary">${links.length?'关联 '+links.length+' 个片段':''}</p>`;}
function refreshLinkStatuses(){document.querySelectorAll('[data-link-status]').forEach(el=>{const l=ensureLinks().links.find(l=>l.id===el.dataset.linkStatus);if(l)el.textContent=linkStatus(l)});}
function placementDialog(c){
 const d=ensureLinks();placement={key:c.key};
 modal('让这段材料进入作品',`<div class="placement-source"><span class="eyebrow">原始片段 · 保留出处</span><blockquote>${esc(c.text)}</blockquote><p>${esc(c.sourceTitle)} · 第 ${c.paragraph+1} 段</p></div><label class="field">放入作品的表达<textarea id="placement-text" rows="4">${esc(c.expression||c.text)}</textarea></label><p class="hint">可以直接引用，也可以先改成自己的表达。原始片段不会被改写。</p><div class="placement-destinations"><label class="destination-check"><input type="checkbox" id="placement-body" checked>正文</label><label class="field">同时放入内页<select id="placement-page" aria-label="指定内页"><option value="">仅放入正文</option>${d.pages.map((p,i)=>`<option value="${p.id}">内页 ${i+1} · ${esc(p.title)}</option>`).join('')}<option value="new" ${d.pages.length>=9?'disabled':''}>新建一张内页</option></select></label></div><div id="placement-preview" class="placement-preview"></div>`,button('取消','close','ghost')+button('放入并关联','v3-apply-placement','primary'));
 updatePlacementPreview();
}
function placementTargets(){if(!placement)return [];const body=$('#placement-body')?.checked,page=$('#placement-page')?.value;return [...(body?['body']:[]),...(page?[page]:[])];}
function updatePlacementPreview(){const d=ensureLinks(),c=d.clips.find(c=>c.key===placement?.key);if(!c)return;const targets=placementTargets(),existing=targets.filter(t=>d.links.some(l=>l.clipKey===c.key&&(t==='body'?l.target==='body':l.pageId===t)));$('#placement-preview').textContent=targets.length?`将追加到${targets.map(t=>t==='body'?'正文':t==='new'?'新内页':'内页 '+(d.pages.findIndex(p=>p.id===t)+1)).join('和')}，保留已有文字。${existing.length?'已关联的位置会跳过，避免重复插入。':''}`:'请至少选择正文或一张内页。';$('#dialog [data-action="v3-apply-placement"]').disabled=!targets.length||!$('#placement-text').value.trim();}
function applyPlacement(){
 const d=ensureLinks(),c=d.clips.find(c=>c.key===placement?.key),text=$('#placement-text')?.value.trim(),targets=placementTargets();if(!c||!text||!targets.length)return;
 const undo={topic:state.selected,changes:[],linkIds:[],newPage:null};c.expression=text;
 for(let target of targets){
  if(d.links.some(l=>l.clipKey===c.key&&(target==='body'?l.target==='body':l.pageId===target)))continue;
  if(target==='new'){if(d.pages.length>=9)continue;const p={id:crypto.randomUUID(),title:'留下一点观察',body:''};d.pages.push(p);target=p.id;undo.newPage=p.id;}
  const obj=target==='body'?d:d.pages.find(p=>p.id===target);if(!obj)continue;
  const before=obj.body,after=before.trim()?before+'\n\n'+text:text;obj.body=after;undo.changes.push({target,before,after});
  const link={id:crypto.randomUUID(),clipKey:c.key,target:target==='body'?'body':'page',pageId:target==='body'?null:target,inserted:text,sourceId:c.sourceId,sourceTitle:c.sourceTitle,paragraph:c.paragraph,range:c.range,original:c.text};d.links.push(link);undo.linkIds.push(link.id);
 }
 closeModal();if(undo.changes.length){placementUndo=undo;save();render();toast(`已放入 ${undo.changes.length} 个位置，出处已关联`);}else toast('选中的位置已经关联过这个片段，没有重复插入');
}
function undoPlacement(){const d=ensureLinks(),u=placementUndo;if(!u||u.topic!==state.selected)return;const safe=u.changes.every(c=>(c.target==='body'?d:d.pages.find(p=>p.id===c.target))?.body===c.after);if(!safe){toast('这些位置已有新修改，已保留；请在编辑页调整');return;}u.changes.forEach(c=>{const obj=c.target==='body'?d:d.pages.find(p=>p.id===c.target);obj.body=c.before});d.links=d.links.filter(l=>!u.linkIds.includes(l.id));if(u.newPage)d.pages=d.pages.filter(p=>p.id!==u.newPage);placementUndo=null;save();render();toast('已撤销最近一次放入');}
function exportLinks(){return ensureLinks().links.map(l=>({...l,location:linkName(l),status:linkStatus(l)}));}
function afterV3Render(){
 const bar=$('.canvas-summary');if(bar){bar.innerHTML=`<span>${draft().clips.length} 个片段 · ${ensureLinks().links.length} 处作品关联${placementUndo?.topic===state.selected?' · 可撤销最近一次放入':''}</span><div class="row">${placementUndo?.topic===state.selected?button('撤销最近放入','v3-undo-placement','ghost'):''}${button(`查看正文 ${icon('arrow')}`,'v2-write','primary')}</div>`;}
}
function handleV3Input(el){if(el.id==='browse-search'){const caret=el.selectionStart;browse.search=el.value;const rows=browserRows();if(!rows.some(f=>f.id===browse.active)){browse.active=null;if(rows.length)selectFragment(rows[0].id)}updateBrowser({wall:true});const input=$('#browse-search');input.focus();input.setSelectionRange(caret,caret);return true;}if(['placement-text','placement-body','placement-page'].includes(el.id)){updatePlacementPreview();return true;}return false;}
document.addEventListener('change',e=>{if(['placement-body','placement-page'].includes(e.target.id))updatePlacementPreview();});
async function handleV3Action(b){
 const a=b.dataset.action,d=ensureLinks();
 if(a==='v3-author'){browse.search=b.dataset.author;browse.active=null;ensureBrowse();updateBrowser({flip:true,wall:true});return;}
 if(a==='v3-kind'||a==='v3-use'||a==='v3-clear'){if(a==='v3-clear')Object.assign(browse,{kind:'all',use:'全部',search:''});else browse[a==='v3-kind'?'kind':'use']=b.dataset.value;const rows=browserRows();if(!rows.some(f=>f.id===browse.active)){browse.active=null;if(rows.length)selectFragment(rows[0].id)}updateBrowser({flip:true,wall:true});return;}
 if(a==='v3-fragment'||a==='v3-index'){selectFragment(b.dataset.fragment);updateBrowser({flip:true});if(a==='v3-index')document.querySelector(`.paper-snippet[data-fragment="${browse.active}"]`)?.scrollIntoView({block:'nearest'});return;}
 if(a==='v3-index-source'){const f=browserRows().find(f=>f.source.id===b.dataset.source);if(f){selectFragment(f.id);updateBrowser({flip:true})}return;}
 if(a==='v3-flip'){const all=spreads(),eligible=availableSpreads(),position=eligible.indexOf(browse.spread);browse.spread=eligible[Math.max(0,Math.min(eligible.length-1,position+Number(b.dataset.direction)))];const p=all[browse.spread],f=browserRows().find(f=>f.source.id===p.source.id&&f.index>=p.start&&f.index<p.start+2);browse.active=f?.id||null;state.researchSource=p.source.id;updateBrowser({flip:true});return;}
 if(a==='v3-parent'){Object.assign(browse,{kind:'all',use:'全部',search:''});const f=fragments().find(f=>f.source.id===b.dataset.source);if(f)selectFragment(f.id);updateBrowser({flip:true,wall:true});return;}
 if(a==='v3-take'){const f=selectedBrowserFragment();if(f){const scroll=$('.snippet-scroll')?.scrollTop||0;addClip(f.source.id,f.index,f.text,{start:f.start,end:f.end});if($('.snippet-scroll'))$('.snippet-scroll').scrollTop=scroll;}return;}
 if(a==='v3-cover-title'){d.previousCover=d.cover;d.cover=d.title;save();render();toast('已带入笔记标题，可调整换行');return;}
 if(a==='v3-undo-cover'){if(d.previousCover!==undefined){d.cover=d.previousCover;delete d.previousCover;save();render();}return;}
 if(a==='v3-place'){const c=d.clips.find(c=>c.key===b.dataset.key);if(c)placementDialog(c);return;}
 if(a==='v3-apply-placement'){applyPlacement();return;}
 if(a==='v3-undo-placement'){undoPlacement();return;}
 if(a==='v3-link-source'){const l=d.links.find(l=>l.id===b.dataset.link);if(l)locateClip({...l,text:l.original});return;}
 if(a==='v3-jump-link'){const l=d.links.find(l=>l.id===b.dataset.link);if(!l)return;if(l.target==='body'){state.step=0;state.writeView='write';}else{const index=d.pages.findIndex(p=>p.id===l.pageId);if(index<0){toast('这一张内页已删除，原始片段仍在');return;}state.step=2;state.inner=index;}navigate('studio');}
}
render();
})();
